import pandas as pd
import numpy as np
from qualitystats.counters import quality_counts

def test_quality_counts():
    # Case 1: Normal
    df1 = pd.DataFrame({"reading": [1.0], "baseline": [2.0]})
    print(f"Case 1: {quality_counts(df1)}") # Expected: {'missing': 0, 'undefined_ratio': 0}

    # Case 2: Missing reading
    df2 = pd.DataFrame({"reading": [np.nan], "baseline": [2.0]})
    print(f"Case 2: {quality_counts(df2)}") # Expected: {'missing': 1, 'undefined_ratio': 0}

    # Case 3: Missing baseline
    df3 = pd.DataFrame({"reading": [1.0], "baseline": [np.nan]})
    print(f"Case 3: {quality_counts(df3)}") # Expected: {'missing': 1, 'undefined_ratio': 0}

    # Case 4: Both missing
    df4 = pd.DataFrame({"reading": [np.nan], "baseline": [np.nan]})
    print(f"Case 4: {quality_counts(df4)}") # Expected: {'missing': 1, 'undefined_ratio': 0}

    # Case 5: 0/0 (Undefined)
    df5 = pd.DataFrame({"reading": [0.0], "baseline": [0.0]})
    print(f"Case 5: {quality_counts(df5)}") # Expected: {'missing': 0, 'undefined_ratio': 1}

    # Case 6: Mixed
    df6 = pd.DataFrame({
        "reading": [1.0, np.nan, 0.0, np.nan],
        "baseline": [2.0, 1.0, 0.0, np.nan]
    })
    print(f"Case 6: {quality_counts(df6)}") # Expected: {'missing': 2, 'undefined_ratio': 1}

test_quality_counts()
